export function toTypedValueCborValue(v: TypedValue): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("kind", v.kind);
  if (v.intValue !== undefined) csilMap.set("int_value", v.intValue);
  if (v.boolValue !== undefined) csilMap.set("bool_value", v.boolValue);
  if (v.textValue !== undefined) csilMap.set("text_value", v.textValue);
  if (v.uintValue !== undefined) csilMap.set("uint_value", v.uintValue);
  if (v.bytesValue !== undefined) csilMap.set("bytes_value", v.bytesValue);
  if (v.floatValue !== undefined) csilMap.set("float_value", v.floatValue);
  if (v.decimalValue !== undefined) csilMap.set("decimal_value", { tag: 4, value: v.decimalValue.toTag4() });
  return csilMap;
}

export function fromTypedValueCborValue(value: CborValue): TypedValue {
  return {
    kind: (asEnumMember(asString(requireKey(value, "kind")), ["null", "bool", "int", "uint", "float", "decimal", "text", "bytes"]) as "null" | "bool" | "int" | "uint" | "float" | "decimal" | "text" | "bytes"),
    boolValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asBool(csilV))(mapGet(value, "bool_value")),
    intValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "int_value")),
    uintValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "uint_value")),
    floatValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asNumber(csilV))(mapGet(value, "float_value")),
    decimalValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : CsilDecimal.fromTag4(asDecimalPayload(csilV)))(mapGet(value, "decimal_value")),
    textValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asString(csilV))(mapGet(value, "text_value")),
    bytesValue: ((csilV: CborValue | undefined) => csilV === undefined ? undefined : asBytes(csilV))(mapGet(value, "bytes_value")),
  };
}

